def calculate_N(m):
    S = list(range(1, m))
    visited = [False] * m
    cycle_count = 0

    for i in S:
        if not visited[i]:
            cycle_count += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = (3 * current) % m
    return cycle_count

def check_m(m):
    if m % 3 == 0:
        return None
    N_m = calculate_N(m)
    return N_m

